  FOR i TO y - LWB b WHILE safe DO
    INT t = b[y - i];
    IF t = x THEN safe := FALSE
    ELIF t = x - i THEN safe := FALSE
    ELIF t = x + i THEN safe := FALSE
    FI
  OD;
  NOT safe
);

