// https://rosettacode.org/wiki/N-queens_problem

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/shm.h>
#include <sys/wait.h>
#include <unistd.h>
typedef uint64_t Bits;
static int N = 8; //  for NxN board
static int count = 0;

static void
solve( int row, Bits column, Bits left, Bits right )
  {
  Bits bit = 1 << N;
  for( int i = 0; i < N; ++i, bit <<= 1 )
    {
    if( bit & (column | left | right) ) continue;
    if( row >= N - 1 ) ++count;
    else solve( row + 1, column | bit, (left | bit) >> 1, (right | bit) << 1);
    }
  return;
  }

int
main(int argc, char *argv[])
  {
  if( argc > 1 ) N = atoi( argv[1] );
  int shmid = shmget(IPC_PRIVATE, N * sizeof(int), IPC_CREAT | 0600);
  int *counts = shmat(shmid, NULL, 0);
  Bits bit = 1 << N;
  for( int i = 0; i < (N + 1) >> 1; i++, bit <<= 1 )
    {
    int pid = fork();
    if( pid > 0 ) printf("parent forked column %2d\n", i);
    else if( pid == 0 ) // child
      {
      solve( 1, bit, bit >> 1, bit << 1 );
      counts[i] = counts[N - 1 - i] = count; // by horizonal reflection
      printf("child completed column %2d with count %d\n", i, count);
      exit(0);
      }
    else { fputs("fork failed\n", stderr); exit(1); }
    }
  while( wait(NULL) > 0 ){} // wait for all children
  for( int i = 0; i < N; i++ ) count += counts[i];
  printf( "N %d count %d\n", N, count );
  }

