template <typename T>
T string_to( const std::string& s )
{
  T result;
  std::istringstream ss( s );
  ss >> result;
  if (!ss.eof()) throw std::runtime_error( "to_string(): invalid conversion" );
  return result;
}

template <typename T, T default_value>
