let good = function(pos, end_idx) {
    return pos.all(function (col_a, row_a) {
        return range(row_a + 1, end_idx).all(function (row_b) {
            let col_b = pos[row_b];
            return not threatens(row_a, col_a, row_b, col_b);
        });
    });
};

